          path: '/docs/version1',
        }),
      ];

      expect(testActiveVersion(versions, '/someUnknownPath')).toBeUndefined();

      expect(testActiveVersion(versions, '/docs/next')?.name).toBe('next');
      expect(testActiveVersion(versions, '/docs/next/')?.name).toBe('next');
      expect(testActiveVersion(versions, '/docs/next/someDoc')?.name).toBe(
