      );

      expect(testActiveVersion(versions, '/docs')?.name).toBe('version2');
      expect(testActiveVersion(versions, '/docs/')?.name).toBe('version2');
      expect(testActiveVersion(versions, '/docs/someDoc')?.name).toBe(
