        'version2',
      );
      expect(testActiveVersion([v2, v1], '/docs/v2/myDoc')?.name).toBe(
        'version2',
      );
    });

    it('getActiveVersion is not sensitive to isLast attribute', () => {
      const v1 = globalVersion({
        name: 'version1',
